9	/** Minimal test runner (no JUnit, no network): runs every public no-arg method whose name starts with "test". */
10	public final class MiniTest {
11	    private MiniTest() {}
12	
13	    /** Optional filter: only classes whose simple name contains one of the given strings run. Returns the failure count. */
14	    public static int run(String[] filter, Class<?>... classes) {
15	        int pass = 0, fail = 0;
16	        for (Class<?> c : classes) {
17	            if (filter.length > 0 && Arrays.stream(filter).noneMatch(f -> c.getSimpleName().contains(f))) continue;
18	            Method[] methods = c.getDeclaredMethods();
19	            Arrays.sort(methods, Comparator.comparing(Method::getName));
20	            for (Method m : methods) {
21	                if (!m.getName().startsWith("test") || !Modifier.isPublic(m.getModifiers()) || m.getParameterCount() != 0) continue;
22	                String name = c.getSimpleName() + "." + m.getName();
23	                try {
24	                    Object o = c.getDeclaredConstructor().newInstance();
25	                    m.invoke(o);
26	                    pass++;
27	                    System.out.println("ok   " + name);
28	                } catch (InvocationTargetException e) {
29	                    fail++;
30	                    System.out.println("FAIL " + name + ": " + e.getCause());
31	                } catch (ReflectiveOperationException e) {
32	                    fail++;
33	                    System.out.println("FAIL " + name + ": cannot run: " + e);
34	                }
35	            }
36	        }
37	        System.out.println(pass + " passed, " + fail + " failed");
38	        return fail;
39	    }
40	}

